import type { Metadata } from "next";

export const SITE_NAME = "QuickSnip";
export const SITE_TAGLINE = "Verified code snippets for humans and AI";
export const SITE_DESCRIPTION =
  "Community-made, tested code snippets. Copy them, install them with the shadcn CLI, or let your AI coding agent use them.";

/** Generated by `src/app/opengraph-image.tsx`. */
const DEFAULT_OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: `${SITE_NAME} — ${SITE_TAGLINE}` };

interface PageMetadataInput {
  title: string;
  description: string;
  /** Path of the page, e.g. `/snippets`. Used for the canonical URL and `og:url`. */
  path: string;
  type?: "website" | "article";
  keywords?: string[];
  noindex?: boolean;
  /** Set when the route has its own `opengraph-image` file, so that image is used instead of the site-wide one. */
  hasOwnImage?: boolean;
}

/**
 * Metadata for a page with consistent canonical, Open Graph and Twitter tags.
 * Next.js replaces (not merges) a parent's `openGraph`/`twitter` objects, so every page
 * repeats the shared fields here, including the site-wide image. Page config also beats
 * a segment's `opengraph-image` file, so routes with their own image pass `hasOwnImage`.
 */
export function pageMetadata({ title, description, path, type = "website", keywords, noindex, hasOwnImage }: PageMetadataInput): Metadata {
  const fullTitle = `${title} · ${SITE_NAME}`;
  // The key must be absent, not `undefined`, or Next.js drops the file-based image too.
  const image = hasOwnImage ? {} : { images: [DEFAULT_OG_IMAGE] };
  return {
    title,
    description,
    keywords,
    alternates: { canonical: path },
    openGraph: { type, url: path, siteName: SITE_NAME, locale: "en_US", title: fullTitle, description, ...image },
    twitter: { card: "summary_large_image", title: fullTitle, description, ...image },
    ...(noindex ? { robots: { index: false, follow: true } } : {}),
  };
}
